/* u008 · Yeni marka: bed4book (bed4book.com · hotel wholesale platform)
   Platformun varsayılan logosu ve renkleri yeni markaya geçer: üst bant, giriş ekranı, platform belgeleri, sekme simgesi.
   Logo, marka dosyasındaki (Bed4Book_Logo_4K.pdf) görselden şeffaf arka planla çıkarıldı; açık tema için koyu, koyu tema için beyaz yazılı iki sürümü var.
   Back Office → Platform markası'ndan logo yüklenirse o logo öncelikli kalır (u001). DMC markaları etkilenmez. Dosyayı kaldırmak eski görünüme döndürür. */
const BRU = B4M.uiBrand;
const WM_L = "data:image/png;base64,";
const WM_D = "data:image/png;base64,";
const ICON = "data:image/png;base64,";
const RATIO = "672 / 150";
const NAME = "bed4book", HOST = "www.bed4book.com", TAG = "hotel wholesale platform", RED = "#E10600";
/* kare simge (kırmızı 4): favicon ve belge başlıklarında */
BRU.amblem = (sz = 52) => `<img class="b4b-ic" src="${ICON}" width="${sz}" height="${sz}" alt="${NAME}" style="flex:none;display:block;border-radius:${Math.round(sz * .19)}px">`;
/* yazı logosu: renkleri temaya göre CSS'ten gelir (her çizimde büyük veri tekrarlanmaz) */
BRU.word = () => `<div class="b4b"><h1 class="b4b-wm" role="img" aria-label="bed4book.com"><span>${NAME}</span></h1><div class="tg b4b-tg">${TAG}</div></div>`;
const baseLogo = BRU.logo, baseDoc = BRU.docHead, pLogo = () => (BRU.pLogo && BRU.pLogo()) || "";
BRU.logo = (x, sz = 52) => !x && !pLogo() ? BRU.word() : baseLogo(x, sz);
/* platform belgeleri beyaz zeminde basılır: koyu yazılı logo <img> olarak (arka plan görselleri yazdırılmayabilir) */
BRU.docHead = (dmc, sub, right) => { if (dmc || pLogo()) return baseDoc(dmc, sub, right);
  return `<div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;border-bottom:2px solid ${RED};padding-bottom:12px;margin-bottom:16px"><div style="display:flex;flex-direction:column;gap:4px"><img src="${WM_L}" alt="bed4book.com" style="height:40px;width:auto;max-width:240px;object-fit:contain;align-self:flex-start"><div style="color:#5d7075">${HOST} · ${sub}</div></div><div style="text-align:end">${right}</div></div>`; };
if (typeof document != "undefined") {
  const st = document.createElement("style"); st.id = "b4b-brand"; st.textContent = `
:root{--ac:var(--brand-ac,#C8102E);--gd:var(--brand-gd,${RED})}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0d0d0f;--sf:#17171a;--ln:#2d2d33;--mu:#a3a3ad;--ac:var(--brand-gd,#FF3B30);--gd:var(--brand-gd,#FF3B30);--on:#fff}}
:root[data-theme="dark"]{--bg:#0d0d0f;--sf:#17171a;--ln:#2d2d33;--mu:#a3a3ad;--ac:var(--brand-gd,#FF3B30);--gd:var(--brand-gd,#FF3B30);--on:#fff}
.b4b{display:flex;flex-direction:column;align-items:stretch;gap:4px}
.b4b-wm{margin:0;height:44px;aspect-ratio:${RATIO};background:url("${WM_L}") left center/contain no-repeat}
.b4b-wm span{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]) .b4b-wm{background-image:url("${WM_D}")}}
:root[data-theme="dark"] .b4b-wm{background-image:url("${WM_D}")}
.b4b-tg{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:500;letter-spacing:2px;color:var(--tx);text-transform:none;margin:0}
.b4b-tg::before,.b4b-tg::after{content:"";flex:1;min-width:14px;height:3px;border-radius:2px;background:${RED}}
#hdr .b4b-wm{height:32px}#hdr .b4b-tg{display:none}
@media(max-width:560px){.b4b-wm{height:36px}#hdr .b4b-wm{height:28px}}`;
  (document.head || document.documentElement).appendChild(st);
  const fav = document.querySelector('link[rel="icon"]'); if (fav) { fav.type = "image/png"; fav.href = ICON; }
}
